// The model answers JSON text, in the Response Format of its model node. Read it into `output`.
// Also takes {"output": {...}} or a ```json block, so a good answer never stops the workflow.
const text = $json.text.trim().replace(/^```(?:json)?\s*|\s*```$/g, '');
const answer = JSON.parse(text);
const wrapped = answer.output && typeof answer.output === 'object' && Object.keys(answer).length === 1;
return { json: { output: wrapped ? answer.output : answer } };

// No reply and no more model calls: build the result in code, in the shape of the case schema.
const triage = $('Triage fields').first().json.output;
const schema = $('Case in').first().json.body.output_schema;
const result = { category: triage.category, flags: triage.flags, reply: '', reasons: 'No reply. ' + triage.reason };
// Only the fields of the schema; a required field we do not know (e.g. route_to) gets an empty value.
const output = {};
for (const [key, prop] of Object.entries(schema.properties)) {
  if (key in result) output[key] = result[key];
  else if ((schema.required || []).includes(key)) output[key] = prop.type === 'array' ? [] : prop.type === 'boolean' ? false : '';
}
return [{ json: { output } }];

